/* Echo · WiWi-Pfad 31021 Investition und Finanzierung (FernUni Hagen).
   Aufbau nach den Klausuren: Teil Investition (Lehrstuhl Hering, 50 P.) und Teil Finanzierung (Lehrstuhl Baule, 50 P.), zusammen 120 Minuten.
   Alle Texte, Fälle und Probeklausuren sind eigene Formulierungen mit eigenen Zahlen; die Original-Klausuren der FernUni werden nicht wiedergegeben. */
'use strict';
const ANF = (i, n) => i === 0 ? 1 / n : i * Math.pow(1 + i, n) / (Math.pow(1 + i, n) - 1);
window.STB_PFAD = {
  ROADMAP: [
    { id: 'inv', n: 'Investition: Rechnen mit Zahlungsreihen', em: '📈', goal: 'Zins- und Rentenrechnung, Annuitätendarlehen, Kapitalwert, Differenzinvestition, Annuität, interner Zins.' },
    { id: 'uns', n: 'Investition: Entscheidungen unter Unsicherheit', em: '🎲', goal: 'Risiko und Ungewissheit, Dominanz, µ- und µ-σ-Prinzip, Bernoulli-Prinzip, Regeln bei Ungewissheit.' },
    { id: 'fin', n: 'Finanzierung', em: '🏦', goal: 'Rechtsformen, Innen- und Außenfinanzierung, Anleihen, Aktien und Kapitalerhöhung, Kapitalstruktur, Märkte, Rendite, Kennzahlen und Cashflow.' },
  ],
  RANKS: [[0, 'Erstsemester'], [10, 'Kommilitone mit Plan'], [30, 'Tutor'], [60, 'Klausurprofi'], [100, '1,0-Kandidat']],
  LESSONS: {
    inv: [
      { id: 'i1', t: 'Grundbegriffe der Investitionsrechnung', norms: ['Zahlungsreihe', 'Unterlassungsalternative', 'vollkommener Kapitalmarkt'],
        why: 'Die Investitionsklausur rechnet ausschließlich mit Zahlungsreihen auf einem vollkommenen Kapitalmarkt. Wer die Modellannahmen kennt, versteht, warum Kapitalwert, Annuität und Endwert immer zum selben Urteil führen.',
        core: ['Eine Investition wird durch ihre Zahlungsreihe beschrieben: e₀, e₁, …, e_T (meist eine Auszahlung in t = 0, dann Einzahlungsüberschüsse). Eine Normalinvestition hat genau einen Vorzeichenwechsel: erst Auszahlungsüberschüsse, danach nur noch Einzahlungsüberschüsse.',
          'Vollkommener Kapitalmarkt unter Sicherheit: ein einheitlicher Soll- und Habenzins, Geld in beliebiger Höhe anlegbar und aufnehmbar, keine Transaktionskosten, Zinsen im Voraus bekannt. Beurteilt wird gegen die Unterlassungsalternative: das Geld stattdessen zum Kalkulationszins anlegen (bzw. Kredit nicht aufnehmen).',
          'Interdependenzen zwischen Projekten: Unabhängigkeit, ein- oder wechselseitige Bedingtheit, gegenseitige Beeinflussung und wechselseitiger Ausschluss. Bei einer Auswahlentscheidung muss genau eines von sich ausschließenden Projekten gewählt werden; bei der Vorteilhaftigkeitsentscheidung steht auch die Unterlassung offen.'],
        schema: ['Zahlungsreihe aufstellen (Zeitpunkte, Vorzeichen)', 'Modellwelt: vollkommener Kapitalmarkt, Kalkulationszins', 'Entscheidung: isoliert (gegen Unterlassung) oder Auswahl?', 'Kennzahl wählen: Kapitalwert, Endwert, Annuität, interner Zins'],
        case: { sv: 'Gegeben sind die Zahlungsreihen A (−200, 30, 30, 30), B (−200, −26, 500, 90), C (−200, 30, −30, 30).',
          steps: [['Welche sind Normalinvestitionen?', 'A und B: Auf Auszahlungsüberschüsse folgen nur noch Einzahlungsüberschüsse (B hat zwei negative Zahlungen zu Beginn, dann nur positive).'], ['Warum nicht C?', 'Nach der ersten Einzahlung folgt wieder eine Auszahlung: mehrere Vorzeichenwechsel.']],
          res: 'A und B sind Normalinvestitionen.' },
        more: [{ sv: 'Projekt B kann nur durchgeführt werden, wenn Projekt A durchgeführt wird; A geht auch allein.', steps: [['Welche Interdependenz?', 'Einseitige Bedingtheit (B setzt A voraus).'], ['Welche Alternativen gibt es?', 'Nichts, nur A, A und B, nicht aber nur B.']], res: 'Einseitige Bedingtheit.' }],
        nav: [],
        cards: [['Was ist eine Normalinvestition?', 'Eine Zahlungsreihe, bei der auf Auszahlungsüberschüsse nur noch Einzahlungsüberschüsse folgen (ein Vorzeichenwechsel).'], ['Vier Prämissen des vollkommenen Kapitalmarkts unter Sicherheit?', 'Einheitlicher Soll- und Habenzins, unbegrenzte Mittelaufnahme und -anlage, keine Transaktionskosten, Zinsen im Voraus bekannt.'], ['Was ist die Unterlassungsalternative?', 'Das Projekt nicht durchzuführen; die Mittel stattdessen zum Kalkulationszins anzulegen bzw. keinen Kredit aufzunehmen.'], ['Auswahlentscheidung?', 'Es muss genau eines von sich gegenseitig ausschließenden Projekten gewählt werden.']] },

      { id: 'i2', t: 'Zinsrechnung: einfach, Zinseszins, periodenindividuell', norms: ['Aufzinsungsfaktor (1+i)^n', 'Abzinsungsfaktor (1+i)^−n'], link: 'i1',
        why: 'Jede spätere Kennzahl ist Auf- oder Abzinsen. Die Klausur prüft das gern an „kuriosen“ Sparverträgen mit einfachen Zinsen oder Zinsen, die sich jedes Jahr ändern.',
        core: ['Einfache Verzinsung: Zinsen nur auf den Anfangsbetrag, C_T = C₀ · (1 + i · T). Zinseszins: Zinsen werden dem Guthaben zugeschlagen und mitverzinst, C_T = C₀ · (1 + i)^T.',
          'Ändert sich der Zins, wird Periode für Periode multipliziert: C_T = C₀ · (1 + i₁) · (1 + i₂) · … · (1 + i_T). Abzinsen ist die Umkehrung: Barwert = C_T · (1 + i)^−T. Das Produkt aus Auf- und Abzinsungsfaktor für gleichen Zins und gleiche Laufzeit ist 1.'],
        schema: ['Einfache Zinsen oder Zinseszins?', 'Konstanter Zins: (1+i)^T; wechselnder Zins: Produkt der Faktoren', 'Auf- oder abzinsen?', 'Runden erst am Ende (Klausur: 2 Nachkommastellen bei Beträgen)'],
        case: { sv: 'Ida legt 20.000 GE für 30 Jahre an: 10 Jahre 2 %, 10 Jahre 3 %, 10 Jahre 5 % (Zinseszins). Ihr Bruder legt 40.000 GE für 30 Jahre zu 2 % einfacher Verzinsung an.',
          steps: [['Endbetrag Ida?', 'Formel: K_{n} = K_{0} · q_{1}^{n_1} · q_{2}^{n_2} · q_{3}^{n_3}\nEingesetzt: 20.000 · 1,02^{10} · 1,03^{10} · 1,05^{10} = 20.000 · 1,21899 · 1,34392 · 1,62889\n= 53.369,97 GE'], ['Endbetrag Bruder?', 'Formel (einfache Verzinsung): K_{n} = K_{0} · (1 + i · n)\nEingesetzt: 40.000 · (1 + 0,02 · 30)\n= 64.000 GE'], ['Wer hat mehr?', 'Der Bruder, trotz einfacher Zinsen, weil er doppelt so viel einzahlt.']],
          res: 'Ida 53.369,97 GE, Bruder 64.000 GE.' },
        more: [{ sv: 'Wie groß ist das Produkt aus Abzinsungsfaktor und Aufzinsungsfaktor für 7 % und 9 Jahre?', steps: [['Rechnung?', 'Abzinsungsfaktor q^{−n}, Aufzinsungsfaktor q^{n}\n1,07^{−9} · 1,07^{9} = 1,07^{0} = 1']], res: 'Immer 1.' }],
        nav: [],
        cards: [['Formel einfache Verzinsung?', 'C_T = C₀ · (1 + i · T).'], ['Endwert bei wechselnden Zinsen?', 'C₀ · (1 + i₁) · (1 + i₂) · … · (1 + i_T).'], ['Produkt aus Auf- und Abzinsungsfaktor (gleicher Zins, gleiche Laufzeit)?', '1.']] },

      { id: 'i3', t: 'Rentenrechnung und Entnahmepläne', norms: ['RBF', 'ANF = 1/RBF', 'ewige Rente'], link: 'i2',
        why: 'Annuitätenfaktor und Rentenbarwertfaktor sind die Werkzeuge für Darlehen, Annuitäten und Entnahmepläne. In fast jeder Klausur fragt mindestens eine Teilaufgabe „Welchen konstanten Betrag kann er jedes Jahr entnehmen?“.',
        core: ['Rentenbarwertfaktor RBF(i, n) = \\frac{(1 + i)^{n} − 1}{i · (1 + i)^{n}}: Barwert von n nachschüssigen Zahlungen der Höhe 1. Der Annuitätenfaktor ist sein Kehrwert, ANF(i, n) = \\frac{i · (1 + i)^{n}}{(1 + i)^{n} − 1}: Er verwandelt einen Betrag in t = 0 in n gleich hohe nachschüssige Zahlungen. Für i = 0 gilt ANF = 1/n.',
          'Ewige Rente: Barwert = Zahlung / i. Konstante Entnahme a aus einem Guthaben C₀ über n Jahre: a = C₀ · ANF(i, n). Bei wechselnden Zinsen gilt: a = C₀ / Σ_t (Abzinsungsfaktor bis t), also C₀ geteilt durch die Summe der Barwerte von je 1 GE.'],
        schema: ['Zahlungen nachschüssig und gleich hoch?', 'Barwert gesucht → RBF; Rate gesucht → ANF', 'Unendlich → ewige Rente Z/i', 'Wechselnde Zinsen → Summe der Abzinsungsfaktoren'],
        case: { sv: 'Herr Lenz hat zum Rentenbeginn 50.000 GE und möchte sie in 20 gleichen Raten jeweils am Jahresende entnehmen; Zins 5 %.',
          steps: [['ANF(5 %, 20)?', 'Formel: ANF(i, n) = \\frac{i · q^{n}}{q^{n} − 1}, q = 1 + i\nEingesetzt: \\frac{0,05 · 1,05^{20}}{1,05^{20} − 1} = \\frac{0,05 · 2,65330}{1,65330}\n= 0,08024'], ['Jährliche Entnahme?', 'Formel: a = K_{0} · ANF(i, n)\nEingesetzt: 50.000 · 0,08024\n= 4.012,13 GE']],
          res: 'a = 4.012,13 GE.' },
        more: [{ sv: 'Aus 30.000 GE sollen drei gleiche Raten entnommen werden; die Zinsen betragen 2 %, 2 % und 1 % in den Jahren 1 bis 3.', steps: [['Abzinsungsfaktoren?', 'Formel: AbF_{t} = \\frac{1}{(1 + i_{1}) · … · (1 + i_{t})}\nAbF_{1} = \\frac{1}{1,02} = 0,98039\nAbF_{2} = \\frac{1}{1,02^{2}} = 0,96117\nAbF_{3} = \\frac{1}{1,02^{2} · 1,01} = 0,95165'], ['Summe und Rate?', 'Formel: a = \\frac{K_{0}}{Σ AbF_{t}}\nΣ AbF = 0,98039 + 0,96117 + 0,95165 = 2,89321\na = \\frac{30.000}{2,89321} = 10.369,10 GE']], res: 'a ≈ 10.369,10 GE.' }],
        nav: [],
        cards: [['Annuitätenfaktor?', 'ANF(i, n) = \\frac{i(1+i)^{n}}{(1+i)^{n} − 1}, Kehrwert des Rentenbarwertfaktors.'], ['ANF bei i = 0?', '1/n.'], ['Barwert einer ewigen Rente?', 'Zahlung / i.'], ['Rate bei wechselnden Zinsen?', 'C₀ geteilt durch die Summe der Abzinsungsfaktoren der Zahlungszeitpunkte.']] },

      { id: 'i4', t: 'Annuitätendarlehen', norms: ['e* = K · ANF', 'Restschuld', 'tilgungsfreie Jahre'], link: 'i3',
        why: 'Eine Standardaufgabe mit festen vier Fragen: Annuität, Gesamtzinsen, Restschuld nach t Jahren, Annuität bei späterem Tilgungsbeginn. Wer das Schema kann, holt hier sichere Punkte.',
        core: ['Die Annuität e* = K · ANF(i, n) bleibt jedes Jahr gleich; ihr Zinsanteil sinkt, ihr Tilgungsanteil steigt. Summe aller Zinsen = n · e* − K.',
          'Restschuld nach t Annuitäten: RS_{t} = K · (1 + i)^{t} − e* · \\frac{(1 + i)^{t} − 1}{i}. Beginnt die Bedienung erst später (keine Zahlungen in den ersten d Jahren, Gesamtlaufzeit unverändert), wächst die Schuld zunächst auf K · (1 + i)^d und wird dann in den verbleibenden n − d Jahren getilgt: e** = K · (1 + i)^d · ANF(i, n − d).'],
        schema: ['e* = K · ANF(i, n)', 'Zinsen gesamt = n · e* − K', 'Restschuld nach t: K(1+i)^{t} − e* · \\frac{(1+i)^{t} − 1}{i}', 'Aufschub d Jahre: e** = K(1+i)^d · ANF(i, n − d)'],
        case: { sv: 'Darlehen 100.000 GE, 10 Jahre, 5 %, Auszahlung 100 %, Annuität jeweils am Jahresende.',
          steps: [['e*?', 'Formel: e* = K · ANF(i, n) = K · \\frac{i · q^{n}}{q^{n} − 1}\nANF(5 %, 10) = \\frac{0,05 · 1,05^{10}}{1,05^{10} − 1} = \\frac{0,05 · 1,62889}{0,62889} = 0,12950\ne* = 100.000 · 0,12950 = 12.950,46 GE'], ['Zinsen gesamt?', 'Formel: Z = n · e* − K\nEingesetzt: 10 · 12.950,46 − 100.000\n= 29.504,57 GE'], ['Restschuld nach 2 Jahren?', 'Formel: RS_{t} = K · q^{t} − e* · \\frac{q^{t} − 1}{i}\nEingesetzt: 100.000 · 1,05^{2} − 12.950,46 · \\frac{1,05^{2} − 1}{0,05} = 110.250 − 12.950,46 · 2,05\n= 110.250 − 26.548,44 = 83.701,56 GE'], ['Erste Zahlung erst nach 3 Jahren (am Ende von Jahr 3)?', 'Formel: e** = K · q^{d} · ANF(i, n − d), hier d = 2 Jahre ohne Zahlung, n − d = 8\nSchuld nach 2 Jahren: 100.000 · 1,05^{2} = 110.250\nANF(5 %, 8) = \\frac{0,05 · 1,05^{8}}{1,05^{8} − 1} = 0,15472\ne** = 110.250 · 0,15472 = 17.058,08 GE']],
          res: 'e* 12.950,46; ZZ 29.504,57; RS₂ 83.701,56; e** 17.058,08 GE.' },
        more: [{ sv: 'Warum sinkt bei einem Annuitätendarlehen der Zinsanteil jedes Jahr?', steps: [['Begründung?', 'Zinsen werden auf die Restschuld berechnet, und die sinkt mit jeder Tilgung; bei gleicher Annuität steigt damit der Tilgungsanteil.']], res: 'Zinsen auf fallende Restschuld.' }],
        nav: [],
        cards: [['Annuität eines Darlehens?', 'e* = K · ANF(i, n).'], ['Gesamtzinsen eines Annuitätendarlehens?', 'n · e* − K.'], ['Restschuld nach t Jahren?', 'K(1+i)^{t} − e* · \\frac{(1+i)^{t} − 1}{i}.'], ['Annuität bei d tilgungs- und zinsfreien Jahren und gleicher Gesamtlaufzeit?', 'e** = K(1+i)^d · ANF(i, n − d).']] },

      { id: 'i5', t: 'Kapitalwert und Endwert', norms: ['K = Σ e_t (1+i)^−t', 'Endwert = K (1+i)^T'], link: 'i3',
        why: 'Der Kapitalwert ist das zentrale Kriterium: Er misst die Vermögensänderung im Planungszeitpunkt. Alle anderen Kennzahlen werden an ihm gemessen.',
        core: ['K = Σ e_t · (1 + i)^−t. Interpretation: Vermögenserhöhung (K > 0) bzw. -minderung (K < 0) im Zeitpunkt t = 0 gegenüber der Unterlassungsalternative. Ein Kapitalwert von 0 bedeutet Indifferenz. Der Endwert ist K · (1 + i)^T; beide Kriterien führen immer zur selben Entscheidung.',
          'Bei periodenindividuellen Zinsen wird jede Zahlung mit dem Produkt der Faktoren bis zu ihrem Zeitpunkt abgezinst: e_t / ((1 + i₁)(1 + i₂)…(1 + i_t)). Bei einer ewigen Rente als Rückfluss gilt K = e₀ + Z / i.'],
        schema: ['Zahlungsreihe', 'Abzinsungsfaktoren (konstant oder periodenindividuell)', 'Summe = Kapitalwert', 'K > 0: vorteilhaft gegenüber Unterlassung; Auswahl: höchster K'],
        case: { sv: 'Zahlungsreihe (−1.000, 300, 400, 500), Zinsen: Periode 1 4 %, Periode 2 3 %, Periode 3 2 %.',
          steps: [['Abzinsungsfaktoren?', 'Formel: AbF_{t} = \\frac{1}{(1 + i_{1}) · … · (1 + i_{t})}\nAbF_{1} = \\frac{1}{1,04} = 0,96154\nAbF_{2} = \\frac{1}{1,04 · 1,03} = 0,93353\nAbF_{3} = \\frac{AbF_{2}}{1,02} = 0,91523'], ['Barwerte?', 'Formel: BW_{t} = e_{t} · AbF_{t}\n300 · 0,96154 = 288,46\n400 · 0,93353 = 373,41\n500 · 0,91523 = 457,62'], ['Kapitalwert?', 'Formel: C_{0} = e_{0} + Σ BW_{t}\n−1.000 + 288,46 + 373,41 + 457,62 = 119,49 GE\nC_{0} > 0: vorteilhaft']],
          res: 'K = 119,49 GE.' },
        more: [{ sv: 'Investition C: −3.000 GE, danach ewig 180 GE pro Jahr; Zins 5 %.', steps: [['Kapitalwert?', 'Formel (ewige Rente): C_{0} = e_{0} + \\frac{e}{i}\n−3.000 + \\frac{180}{0,05} = −3.000 + 3.600\n= 600 GE']], res: 'K = 600 GE.' }],
        nav: [],
        cards: [['Interpretation des Kapitalwerts?', 'Vermögensänderung im Planungszeitpunkt gegenüber der Unterlassungsalternative.'], ['Kapitalwert bei periodenindividuellen Zinsen?', 'Jede Zahlung durch das Produkt der Zinsfaktoren bis zu ihrem Zeitpunkt teilen.'], ['Kapitalwert mit ewiger Rente?', 'K = e₀ + Z/i.'], ['Verhältnis Kapitalwert zu Endwert?', 'Endwert = K(1+i)^T; gleiche Entscheidung.']] },

      { id: 'i6', t: 'Differenzinvestition und Auswahl', norms: ['D_A,B = A − B', 'relative Vorteilhaftigkeit'], link: 'i5',
        why: 'Statt zwei Kapitalwerte auszurechnen, genügt bei einer Auswahl der Kapitalwert der Differenzreihe. Die Klausur fragt aber auch nach den Grenzen dieser Aussage.',
        core: ['Differenzzahlungsreihe D_A,B = e_t(A) − e_t(B) für jeden Zeitpunkt; bei unterschiedlicher Laufzeit fehlende Zahlungen als 0. K(D) = K(A) − K(B): Ist er positiv, ist A relativ vorteilhafter als B.',
          'Grenzen: Die Differenzreihe ist kein real durchführbares Projekt und sagt nichts über die absolute Vorteilhaftigkeit (gegenüber der Unterlassung) aus. Für eine echte Auswahlentscheidung, bei der eines der Projekte zwingend gewählt wird, reicht sie aus.'],
        schema: ['Zeitachsen angleichen (fehlende Zahlungen = 0)', 'D_t = e_t(A) − e_t(B)', 'K(D) berechnen', 'K(D) > 0 → A relativ besser; absolute Vorteilhaftigkeit separat prüfen'],
        case: { sv: 'A (−800, 200, 400, 450), B (−300, 0, 500); Zins 5 %.',
          steps: [['Differenzreihe A − B?', 'Formel: Differenzreihe d_{t} = e_{t}^{A} − e_{t}^{B} je Zeitpunkt (fehlende Zahlungen = 0)\nEingesetzt: t0: −800 − (−300); t1: 200 − 0; t2: 400 − 500; t3: 450 − 0\nErgebnis: (−500, 200, −100, 450)'], ['Kapitalwert der Differenz?', 'Formel: C_{0} = Σ \\frac{e_{t}}{q^{t}}\n−500 + \\frac{200}{1,05} − \\frac{100}{1,05^{2}} + \\frac{450}{1,05^{3}}\n= −500 + 190,48 − 90,70 + 388,73 = −11,50 GE'], ['Folgerung?', 'B ist relativ vorteilhafter (K(A) < K(B)).']],
          res: 'B vor A.' },
        more: [{ sv: 'Sagt K(D_A,B) = +50 etwas darüber, ob A überhaupt durchgeführt werden sollte?', steps: [['Antwort?', 'Nein. Nur die relative Vorteilhaftigkeit; sind beide Kapitalwerte negativ, ist die Unterlassung besser.']], res: 'Nur relative Aussage.' }],
        nav: [],
        cards: [['Wie bildet man die Differenzreihe bei unterschiedlichen Laufzeiten?', 'Fehlende Zahlungen als 0 ansetzen und zeitpunktweise subtrahieren.'], ['Was sagt K(D_A,B) > 0?', 'A hat den höheren Kapitalwert als B (relative Vorteilhaftigkeit).'], ['Ist die Differenzreihe ein reales Projekt?', 'Nein; sie dient nur dem Vergleich.']] },

      { id: 'i7', t: 'Äquivalente Annuität', norms: ['a = K · ANF(i, T)'], link: 'i6',
        why: 'Die Praxis denkt in Jahresgrößen. Die Annuität verteilt den Kapitalwert gleichmäßig auf die Laufzeit, ist aber bei unterschiedlichen Laufzeiten eine Falle.',
        core: ['Äquivalente Annuität a = K · ANF(i, T): der Betrag, den der Investor zusätzlich in jedem Jahr der Laufzeit entnehmen könnte. Für ein einzelnes Projekt führt sie zur selben Entscheidung wie der Kapitalwert (Vorzeichen gleich).',
          'Bei Auswahl zwischen Projekten mit unterschiedlicher Laufzeit kann die höhere laufzeitindividuelle Annuität in die Irre führen, wenn das Projekt mit der niedrigeren Annuität länger läuft. Korrekt ist dann der Vergleich der Kapitalwerte oder der Annuitäten über einen einheitlichen Zeitraum.'],
        schema: ['Kapitalwert bestimmen', 'ANF(i, T) mit der Projektlaufzeit', 'a = K · ANF', 'Auswahl bei ungleichen Laufzeiten: Kapitalwert oder einheitliche Basis'],
        case: { sv: 'A: K = 300 GE, Laufzeit 5 Jahre. B: K = 280 GE, Laufzeit 2 Jahre. Zins 5 %.',
          steps: [['Annuitäten?', 'Formel: a = C_{0} · ANF(i, n)\na_{A} = 300 · ANF(5 %, 5) = 300 · 0,23097 = 69,29 GE\na_{B} = 280 · ANF(5 %, 2) = 280 · 0,53780 = 150,59 GE'], ['Wahl nach Annuität?', 'B.'], ['Richtige Wahl?', 'A: höherer Kapitalwert, also höheres Endvermögen; die Annuität von B ist nur höher, weil sie auf weniger Jahre verteilt wird.']],
          res: 'A nach Kapitalwert.' },
        more: [{ sv: 'Interpretieren Sie eine Annuität von 120 GE über 4 Jahre.', steps: [['Bedeutung?', 'Der Investor kann bei Durchführung in jedem der 4 Jahre 120 GE mehr entnehmen als bei Unterlassung, bei gleichem Endvermögen.']], res: 'Zusätzliche jährliche Entnahme.' }],
        nav: [],
        cards: [['Äquivalente Annuität?', 'a = K · ANF(i, T); zusätzliche gleich hohe Entnahme pro Jahr der Laufzeit.'], ['Wann führt die Annuität zu Fehlentscheidungen?', 'Bei Auswahl zwischen Projekten mit unterschiedlicher Laufzeit, wenn das Projekt mit der niedrigeren Annuität länger läuft.'], ['Stimmen Annuität und Kapitalwert bei einem einzelnen Projekt überein?', 'Ja, gleiches Vorzeichen, gleiche Entscheidung.']] },

      { id: 'i8', t: 'Interner Zinsfuß', norms: ['K(r*) = 0'], link: 'i5',
        why: 'Die Rendite eines Projekts ist anschaulich, aber nur unter Bedingungen ein gutes Kriterium. In der Klausur wird r* in Spezialfällen exakt berechnet, die du erkennen musst.',
        core: ['Der interne Zinsfuß r* ist der Zins, bei dem der Kapitalwert null wird. Exakt lösbar: ein Rückfluss nach T Jahren: r* = (e_T / |e₀|)^(1/T) − 1; ewige Rente: r* = Z / |e₀|; zwei Perioden: quadratische Gleichung in q = 1 + r: |e₀| q² − e₁ q − e₂ = 0, q = (e₁ + √(e₁² + 4|e₀|e₂)) / (2|e₀|).',
          'Bei Normalinvestitionen existiert genau ein positiver r* (Kapitalwertfunktion fällt streng monoton). Isoliert gilt: r* > i ⇔ K > 0. Für Auswahlentscheidungen ist r* untauglich, weil Projektgröße und Laufzeit unterschiedlich sein können; hier entscheidet der Kapitalwert.'],
        schema: ['Normalinvestition? (Eindeutigkeit)', 'Spezialfall erkennen: Einzelrückfluss, ewige Rente, zwei Perioden', 'Sonst: Näherung (Interpolation)', 'Isoliert: r* mit i vergleichen; Auswahl: Kapitalwert'],
        case: { sv: 'D: (−1.500, 0, 0, 1.950); C: (−2.988, ewig 175 pro Jahr); E: (−2.000, 960, 1.296).',
          steps: [['r*(D)?', 'Formel (eine Rückzahlung nach T Jahren): r* = (\\frac{e_{T}}{A_{0}})^{1/T} − 1\n(\\frac{1.950}{1.500})^{1/3} − 1 = 1,3^{1/3} − 1\n= 0,0914 = 9,14 %'], ['r*(C)?', 'Formel (ewige Rente): r* = \\frac{e}{A_{0}}\n\\frac{175}{2.988} = 0,0586 = 5,86 %'], ['r*(E)?', 'Ansatz: −2.000 + \\frac{960}{q} + \\frac{1.296}{q^{2}} = 0; mal q^{2}: 2.000 q^{2} − 960 q − 1.296 = 0\nFormel (positive Lösung): q = \\frac{960 + \\sqrt{960^{2} + 4 · 2.000 · 1.296}}{2 · 2.000}\n= \\frac{960 + \\sqrt{921.600 + 10.368.000}}{4.000} = \\frac{960 + 3.360}{4.000} = 1,08\nr* = q − 1 = 8 %']],
          res: 'r*(D) 9,14 %, r*(C) 5,86 %, r*(E) 8 %.' },
        more: [{ sv: 'C hat r* = 5,86 % und K = 14.512 GE, D hat r* = 9,14 % und K = 392 GE (Zins 1 %). Welche Wahl maximiert das Endvermögen?', steps: [['Entscheidung?', 'C: Bei Auswahl entscheidet der Kapitalwert, nicht der interne Zins.']], res: 'C wählen.' }],
        nav: [],
        cards: [['Definition interner Zinsfuß?', 'Der Kalkulationszins, bei dem der Kapitalwert null ist.'], ['r* bei einem einzigen Rückfluss nach T Jahren?', '(e_T/|e₀|)^(1/T) − 1.'], ['r* bei ewiger Rente?', 'Z/|e₀|.'], ['Ist r* für Auswahlentscheidungen geeignet?', 'Nein, dafür ist der Kapitalwert maßgeblich; r* nur für isolierte Beurteilung (r* > i ⇔ K > 0) bei Normalinvestitionen.']] },
    ],
    uns: [
      { id: 'n1', t: 'Risiko, Ungewissheit und Dominanz', norms: ['Ergebnismatrix', 'Zustandsdominanz'],
        why: 'Unsicherheit wird als Matrix aus Handlungsalternativen, Umweltzuständen und Ergebnissen modelliert. Bevor eine Entscheidungsregel greift, lassen sich dominierte Alternativen streichen.',
        core: ['Risikosituation: Den Umweltzuständen sind Eintrittswahrscheinlichkeiten zugeordnet. Ungewissheitssituation: Mangels Informationen sind keine Wahrscheinlichkeiten angebbar.',
          'Dominanz: Eine Alternative dominiert eine andere, wenn sie in keinem Zustand schlechter und in mindestens einem besser ist (Zustandsdominanz). Dominierte Alternativen scheiden aus, unabhängig von der Risikoeinstellung.'],
        schema: ['Ergebnismatrix aufstellen', 'Wahrscheinlichkeiten bekannt? → Risiko; sonst Ungewissheit', 'Dominierte Alternativen streichen', 'Entscheidungsregel anwenden'],
        case: { sv: 'Alternativen in den Zuständen s1/s2/s3: A (10, 20, 30), B (12, 20, 30), C (40, 0, 5).',
          steps: [['Dominanz?', 'B dominiert A (nie schlechter, in s1 besser).'], ['Verbleibend?', 'B und C; zwischen ihnen entscheidet eine Regel (keine Dominanz).']],
          res: 'A scheidet aus.' },
        nav: [],
        cards: [['Risiko vs. Ungewissheit?', 'Risiko: Wahrscheinlichkeiten bekannt; Ungewissheit: keine Wahrscheinlichkeiten angebbar.'], ['Zustandsdominanz?', 'Alternative ist in keinem Zustand schlechter und in mindestens einem besser.']] },

      { id: 'n2', t: 'µ-Prinzip und µ-σ-Prinzip', norms: ['µ = Σ p x', 'σ² = Σ p (x − µ)²'], link: 'n1',
        why: 'Das µ-σ-Prinzip bewertet Verteilungen über Erwartungswert und Streuung. Die Ableitung der Präferenzfunktion nach σ entscheidet über die Risikoeinstellung, eine klassische Ankreuzfrage.',
        core: ['µ-Prinzip: Bewertung nur nach dem Erwartungswert, Risikoneutralität. µ-σ-Prinzip: Präferenzfunktion Φ(µ, σ). ∂Φ/∂σ < 0: Risikoaversion; ∂Φ/∂σ = 0: Risikoneutralität; ∂Φ/∂σ > 0: Risikofreude.',
          'Beispiel einer Präferenzfunktion: Φ = µ − α · σ² mit α > 0 (risikoavers). Kritik: Die Verteilung wird auf zwei Kennzahlen reduziert; das kann zu Entscheidungen führen, die der Zustandsdominanz widersprechen.'],
        schema: ['µ und σ jeder Alternative', 'Präferenzfunktion Φ(µ, σ) einsetzen', 'Höchstes Φ wählen', 'Risikoeinstellung über ∂Φ/∂σ deuten'],
        case: { sv: 'A: 100 oder 200 je mit 50 %. B: sicher 140. Φ = µ − 0,01 · σ².',
          steps: [['µ und σ² von A?', 'Formeln: µ = Σ p_{s} · x_{s}; σ^{2} = Σ p_{s} · (x_{s} − µ)^{2}\nµ = 0,5 · 100 + 0,5 · 200 = 150\nσ^{2} = 0,5 · (100 − 150)^{2} + 0,5 · (200 − 150)^{2} = 2.500'], ['Φ(A)?', 'Formel: Φ = µ − 0,01 · σ^{2}\nEingesetzt: µ = 0,5 · 100 + 0,5 · 200 = 150; σ^{2} = 0,5 · (100 − 150)^{2} + 0,5 · (200 − 150)^{2} = 2.500; Φ = 150 − 0,01 · 2.500\nErgebnis: Φ(A) = 125'], ['Φ(B)?', '140. B wird gewählt.']],
          res: 'B (Risikoaversion).' },
        nav: [],
        cards: [['Wann ist eine µ-σ-Präferenzfunktion risikoneutral?', 'Wenn ∂Φ/∂σ = 0, also nur der Erwartungswert zählt.'], ['Risikoaversion im µ-σ-Prinzip?', '∂Φ/∂σ < 0.'], ['Schwäche des µ-σ-Prinzips?', 'Kann der Zustandsdominanz widersprechen, weil nur zwei Kennzahlen verwendet werden.']] },

      { id: 'n3', t: 'Bernoulli-Prinzip', norms: ['EU = Σ p · u(x)', 'Sicherheitsäquivalent'], link: 'n2',
        why: 'Das Bernoulli-Prinzip ist das theoretisch fundierte Kriterium: Es bewertet jedes Ergebnis mit einer Nutzenfunktion und bildet dann den Erwartungswert.',
        core: ['Erwartungsnutzen EU = Σ p_s · u(x_s); gewählt wird die Alternative mit dem höchsten Erwartungsnutzen. Konkave Nutzenfunktion (z. B. √x, ln x): Risikoaversion; linear: Neutralität; konvex: Risikofreude.',
          'Sicherheitsäquivalent SÄ: der sichere Betrag mit gleichem Nutzen, u(SÄ) = EU, bei u = √x also SÄ = EU². Risikoprämie = µ − SÄ (bei Aversion positiv).'],
        schema: ['Nutzen jedes Ergebnisses u(x)', 'Erwartungsnutzen Σ p u(x)', 'Vergleich der EU', 'SÄ = u⁻¹(EU), Risikoprämie µ − SÄ'],
        case: { sv: 'Lotterie: 100 oder 400 je mit 50 %; u(x) = √x.',
          steps: [['EU?', 'Formel: EU = Σ p_{s} · u(x_{s})\n0,5 · \\sqrt{100} + 0,5 · \\sqrt{400} = 0,5 · 10 + 0,5 · 20\n= 15'], ['SÄ?', 'Formel: u(SÄ) = EU, also SÄ = u^{−1}(EU)\n\\sqrt{SÄ} = 15 → SÄ = 15^{2} = 225'], ['Risikoprämie?', 'Formel: Risikoprämie = µ − Sicherheitsäquivalent\nEingesetzt: µ = 0,5 · 100 + 0,5 · 400 = 250; 250 − 225\nErgebnis: Risikoprämie = 25']],
          res: 'SÄ 225, Risikoprämie 25.' },
        nav: [],
        cards: [['Bernoulli-Prinzip?', 'Wahl nach maximalem Erwartungsnutzen Σ p · u(x).'], ['Sicherheitsäquivalent bei u = √x?', 'SÄ = (Σ p √x)².'], ['Konkave Nutzenfunktion bedeutet?', 'Risikoaversion.']] },

      { id: 'n4', t: 'Regeln bei Ungewissheit', norms: ['Maximin', 'Maximax', 'Hurwicz', 'Savage-Niehans', 'Laplace'], link: 'n1',
        why: 'Ohne Wahrscheinlichkeiten bleiben nur Regeln, die unterschiedliche Haltungen zum Risiko abbilden. Die Klausur verlangt, sie an einer Matrix anzuwenden.',
        core: ['Maximin (Wald): wähle die Alternative mit dem besten schlechtesten Ergebnis (pessimistisch). Maximax: bestes bestes Ergebnis. Hurwicz: λ · Maximum + (1 − λ) · Minimum mit Optimismusparameter λ.',
          'Savage-Niehans (minimax regret): Bedauernsmatrix aus Differenz zum besten Ergebnis je Zustand bilden, dann das kleinste maximale Bedauern wählen. Laplace: alle Zustände gleich wahrscheinlich, Durchschnitt maximieren.'],
        schema: ['Matrix', 'Regel wählen', 'Je Alternative Kennzahl berechnen', 'Optimum bestimmen'],
        case: { sv: 'B (12, 20, 30) und C (40, 0, 5); λ = 0,6.',
          steps: [['Maximin?', 'min B = 12, min C = 0 → B.'], ['Hurwicz?', 'Formel: H = λ · max + (1 − λ) · min\nB: 0,6 · 30 + 0,4 · 12 = 22,8\nC: 0,6 · 40 + 0,4 · 0 = 24 → C'], ['Savage-Niehans?', 'Bedauern B (28, 0, 0), C (0, 20, 25); max 28 vs. 25 → C.'], ['Laplace?', 'Formel: L = \\frac{1}{S} · Σ x_{s}\nB: \\frac{12 + 20 + 30}{3} = 20,67\nC: \\frac{40 + 0 + 5}{3} = 15 → B']],
          res: 'Je nach Regel B oder C.' },
        nav: [],
        cards: [['Maximin-Regel?', 'Alternative mit dem besten schlechtesten Ergebnis.'], ['Hurwicz-Regel?', 'λ · max + (1 − λ) · min, λ = Optimismusparameter.'], ['Savage-Niehans?', 'Minimiere das maximale Bedauern (Differenz zum jeweils besten Ergebnis eines Zustands).'], ['Laplace-Regel?', 'Gleiche Wahrscheinlichkeiten, Durchschnitt maximieren.']] },
    ],
    fin: [
      { id: 'f1', t: 'Rechtsformen und Finanzierung', norms: ['Personen- vs. Kapitalgesellschaft'],
        why: 'Wie ein Unternehmen Kapital beschaffen kann, hängt an seiner Rechtsform: Haftung, Übertragbarkeit der Anteile, Besteuerung und Zugang zum Kapitalmarkt.',
        core: ['Personengesellschaften (GbR, OHG, KG): Gesellschafter haften (Komplementäre) unbeschränkt, Gewinne werden bei den Gesellschaftern besteuert, Anteile sind schwer übertragbar, Gesellschafter können natürliche oder juristische Personen sein. In der KG gibt es Komplementäre (unbeschränkte Haftung, Geschäftsführung) und Kommanditisten (Haftung bis zur Einlage, grundsätzlich keine Geschäftsführung); die Gewinnverteilung ist vertraglich frei gestaltbar.',
          'Kapitalgesellschaften (GmbH, AG): Haftung auf das Gesellschaftsvermögen beschränkt, Körperschaftsteuer auf Ebene der Gesellschaft, bei der AG leicht übertragbare Anteile und Zugang zur Börse, dafür höhere Publizitäts- und Formvorschriften.'],
        schema: ['Haftung', 'Geschäftsführung', 'Besteuerung', 'Übertragbarkeit, Kapitalmarktzugang'],
        case: { sv: 'Welche Aussagen zur KG stimmen? 1) Komplementäre haften unbeschränkt. 2) Alle Gesellschafter führen die Geschäfte. 3) Gesellschafter müssen natürliche Personen sein. 4) Gewinne können flexibel verteilt werden.',
          steps: [['Bewertung?', '1) richtig, 2) falsch (Kommanditisten nicht), 3) falsch (z. B. GmbH als Komplementärin), 4) richtig.']], res: 'Richtig: 1 und 4.' },
        nav: [],
        cards: [['Wo werden Gewinne einer Personengesellschaft besteuert?', 'Bei den Gesellschaftern (ESt), nicht bei der Gesellschaft.'], ['Haftung von Komplementär und Kommanditist?', 'Komplementär unbeschränkt, Kommanditist bis zur Höhe seiner Einlage.'], ['Vorteil der AG für große Investoren?', 'Leichte Übertragbarkeit der Anteile, Börsenzugang.']] },

      { id: 'f2', t: 'Innenfinanzierung', norms: ['Selbstfinanzierung', 'Abschreibungs- und Rückstellungsgegenwerte'], link: 'f1',
        why: 'Ein Teil der Mittel für Investitionen kommt aus dem Umsatzprozess selbst. Die Klausur rechnet die verfügbaren internen Mittel aus Bilanz- und GuV-Größen.',
        core: ['Innenfinanzierung: Mittel aus dem Umsatzprozess. Dazu gehören die Selbstfinanzierung (einbehaltene Gewinne, ist Eigenfinanzierung), die Finanzierung aus Abschreibungs- und Rückstellungsgegenwerten (nicht auszahlungswirksamer Aufwand) und im weiteren Sinne Vermögensumschichtung (z. B. Verkauf nicht betriebsnotwendigen Vermögens). Innenfinanzierung ist nicht immer Eigenfinanzierung: Rückstellungen sind Fremdkapital.',
          'Kapazitätserweiterungseffekt (Lohmann-Ruchti): Werden verdiente Abschreibungsgegenwerte sofort reinvestiert, wächst die Zahl der Anlagen, ohne zusätzliches Kapital. Verfügbare interne Mittel (Klausurschema): Jahresüberschuss + Abschreibungen + Zuführung zu Rückstellungen − Zunahme Vorräte − Zunahme Forderungen + Zunahme kurzfristiger Verbindlichkeiten + vorhandene liquide Mittel.'],
        schema: ['Jahresüberschuss', '+ nicht zahlungswirksame Aufwendungen (Abschreibungen, Zuführung Rückstellungen)', '− Zunahme Umlaufvermögen (Vorräte, Forderungen), + Zunahme kurzfristiger Verbindlichkeiten', '+ Anfangsbestand liquider Mittel = verfügbare Mittel'],
        case: { sv: 'Jahresüberschuss 80, Abschreibungen 100, Zuführung Rückstellungen 15, Vorräte +20, Forderungen +10, kurzfristige Verbindlichkeiten −5, liquide Mittel Vorjahr 30 (TEUR). Investitionsbedarf 250.',
          steps: [['Interne Mittel?', 'Formel: interne Mittel = Jahresüberschuss + Abschreibungen + Zuführung Rückstellungen − Zunahme Vorräte − Zunahme Forderungen − Abnahme kurzfr. Verbindlichkeiten + liquide Mittel Vorjahr\nEingesetzt: 80 + 100 + 15 − 20 − 10 − 5 + 30\nErgebnis: 190 TEUR'], ['Externer Bedarf?', 'Formel: externer Bedarf = Investitionsbedarf − interne Mittel\nEingesetzt: 250 − 190\nErgebnis: 60 TEUR'], ['Geeignet: Darlehen oder Kontokorrentkredit?', 'Darlehen (langfristig, planbar); Kontokorrent ist für kurzfristige Engpässe und teuer.']],
          res: '190 TEUR intern, 60 TEUR extern per Darlehen.' },
        nav: [],
        cards: [['Ist Innenfinanzierung immer Eigenfinanzierung?', 'Nein, Finanzierung aus Rückstellungsgegenwerten ist Fremdfinanzierung.'], ['Kapazitätserweiterungseffekt?', 'Reinvestition verdienter Abschreibungsgegenwerte erhöht die Zahl der Anlagen ohne zusätzliches Kapital.'], ['Schema verfügbare interne Mittel?', 'JÜ + Abschreibungen + Rückstellungszuführung − ΔVorräte − ΔForderungen + Δkurzfristige Verbindlichkeiten + liquide Mittel.']] },

      { id: 'f3', t: 'Fremdkapital: Kredite, Leasing, Lieferantenkredit', norms: ['Skonto-Effektivzins'], link: 'f2',
        why: 'Welches Instrument zu welchem Zweck passt, ist eine typische Begründungsaufgabe. Fristenkongruenz ist das Leitprinzip.',
        core: ['Langfristige Investitionen sind fristenkongruent langfristig zu finanzieren: Darlehen (planbare Zins- und Tilgung), Leasing (Nutzung ohne Kaufpreis, planbare Raten), bei Großunternehmen Anleihen (hoher Emissionsaufwand). Kontokorrentkredite dienen kurzfristigen Liquiditätsengpässen: flexibel, aber teuer.',
          'Lieferantenkredit: Verzicht auf Skonto ist ein sehr teurer Kredit. Näherung für den Jahreszins: Skontosatz / (1 − Skontosatz) · 360 / (Zahlungsziel − Skontofrist). Beispiel 2 % Skonto bei 10 Tagen, Ziel 30 Tage: 0,02/0,98 · 360/20 = 36,7 %.'],
        schema: ['Zweck und Laufzeit des Kapitalbedarfs', 'Fristenkongruenz prüfen', 'Kosten vergleichen (Effektivzins)', 'Begründung: Planbarkeit, Aufwand, Flexibilität'],
        case: { sv: 'Lieferant: 3 % Skonto bei Zahlung innerhalb von 10 Tagen, sonst 40 Tage. Kontokorrentzins 12 %.',
          steps: [['Kosten des Lieferantenkredits?', 'Formel: i_{eff} ≈ \\frac{s}{1 − s} · \\frac{360}{Zahlungsziel − Skontofrist}\n\\frac{0,03}{0,97} · \\frac{360}{40 − 10} = 0,03093 · 12\n= 37,1 % p. a.'], ['Entscheidung?', 'Skonto nutzen und notfalls den Kontokorrentkredit (12 %) ziehen.']],
          res: 'Skonto ziehen.' },
        nav: [],
        cards: [['Effektivzins des Lieferantenkredits (Näherung)?', 's/(1 − s) · 360/(Zahlungsziel − Skontofrist).'], ['Warum ist ein Kontokorrentkredit für eine Maschine ungeeignet?', 'Er ist für kurzfristige Engpässe gedacht und teuer; keine Fristenkongruenz.'], ['Vorteil des Leasings?', 'Sofortige Nutzung ohne Kaufpreis, planbare Raten.']] },

      { id: 'f4', t: 'Anleihen', norms: ['Effektivzins-Näherung', 'Nullkupon', 'Floater', 'Stückzinsen'], link: 'f3',
        why: 'Anleihen sind der Klassiker der Fremdfinanzierung am Kapitalmarkt. Die Klausur rechnet Effektivzinsen, Zinszahlungen von Floatern und Stückzinsen.',
        core: ['Effektivzins einer Kuponanleihe, Näherungsformel: i_eff ≈ (i_nom + d/T) / (1 − d), mit Disagio d = 1 − Ausgabekurs (in Dezimalform) und Laufzeit T; allgemein (i_nom + (1 − C₀)/T) / C₀. Nullkuponanleihe: i_eff = (1/C₀)^(1/T) − 1.',
          'Floater: variabler Zins = zinsperiodenkongruenter Referenzzins (z. B. 6-Monats-EURIBOR bei halbjährlicher Zahlung) zu Beginn der Zinsperiode + Aufschlag; Zinsbetrag bei halbjährlicher Zahlung ≈ Volumen · Satz / 2. Stückzinsen bei Verkauf zwischen Zinsterminen: Nominal · Kupon · Tage/360; Börsenkurs ohne Stückzinsen = clean price, mit = dirty price.'],
        schema: ['Anleihetyp erkennen', 'Kupon, Ausgabekurs, Laufzeit', 'Formel: Näherung, Nullkupon, Floater', 'Stückzinsen und dirty price'],
        case: { sv: 'Kuponanleihe 4 %, Ausgabe 98 %, Laufzeit 5 Jahre; Nullkupon mit Ausgabekurs 80 %, 5 Jahre.',
          steps: [['Effektivzins Kuponanleihe?', 'Formel (Näherung): r ≈ \\frac{Kupon + \\frac{Rückzahlung − Ausgabekurs}{n}}{Ausgabekurs}\n\\frac{0,04 + \\frac{1 − 0,98}{5}}{0,98} = \\frac{0,044}{0,98}\n= 4,49 %'], ['Nullkupon?', 'Formel: r = (\\frac{Rückzahlung}{Kurs})^{1/n} − 1\n(\\frac{1}{0,80})^{1/5} − 1 = 1,25^{1/5} − 1\n= 4,56 %'], ['Welche rentiert besser?', 'Die Nullkuponanleihe, knapp.']],
          res: '4,49 % vs. 4,56 %.' },
        more: [{ sv: 'Festzinsanleihe 3 %, Nominal 20.000 €, Verkauf 120 Tage nach dem letzten Zinstermin; Kurs 100,4 % clean, Stückzinsen 1 %.', steps: [['Stückzinsen in €?', 'Formel: SZ = Nominal · Kupon · \\frac{Tage}{360}\n20.000 · 0,03 · \\frac{120}{360}\n= 200 €'], ['Dirty price?', 'Formel: Dirty Price = Clean Price + Stückzinsen\n100,4 % + 1 % = 101,4 %']], res: '200 € Stückzinsen, dirty 101,4 %.' }],
        nav: [],
        cards: [['Näherungsformel Effektivzins Kuponanleihe?', '(i_nom + (1 − C₀)/T) / C₀.'], ['Effektivzins Nullkuponanleihe?', '(1/C₀)^(1/T) − 1.'], ['Welcher EURIBOR bei halbjährlichem Floater?', 'Der 6-Monats-EURIBOR zu Beginn der jeweiligen Zinsperiode.'], ['Dirty price?', 'Clean price + Stückzinsen.']] },

      { id: 'f5', t: 'Aktien und Kapitalerhöhung', norms: ['Mischkurs', 'Bezugsrecht', 'Kapitalschnitt'], link: 'f1',
        why: 'Eigenkapital von außen bekommt eine AG über Kapitalerhöhungen. Rechnerisch geht es um Mischkurs und Bezugsrecht, begrifflich um Nennwert und Börsenkurs.',
        core: ['Stammaktien verbriefen in der Regel eine Stimme; Vorzugsaktien bevorzugen bei der Dividende, oft ohne Stimmrecht. Grundkapital = Summe der Nennwerte. Neue Aktien werden auf dem Primärmarkt ausgegeben, gehandelt wird auf dem Sekundärmarkt.',
          'Ordentliche Kapitalerhöhung: Ausgabe nicht unter dem Nennwert, also nur möglich, wenn der Nennwert unter dem Börsenkurs liegt; sonst zuerst Kapitalschnitt (Verlust wird auf das gezeichnete Kapital übertragen). Theoretischer Mischkurs = (n_alt · P_alt + n_neu · P_neu) / (n_alt + n_neu). Rechnerischer Wert des Bezugsrechts = (P_alt − P_neu) / (BV + 1), BV = n_alt / n_neu.'],
        schema: ['Nennwert vs. Börsenkurs (Zulässigkeit)', 'Mischkurs berechnen', 'Bezugsrecht berechnen', 'Vermögenseffekt für Altaktionäre'],
        case: { sv: '2 Mio. Aktien zu 30 €; 500.000 neue Aktien zu 20 €.',
          steps: [['Mischkurs?', 'Formel: K_{m} = \\frac{n_{alt} · K_{alt} + n_{neu} · K_{neu}}{n_{alt} + n_{neu}}\n\\frac{2.000.000 · 30 + 500.000 · 20}{2.500.000}\n= 28 €'], ['Bezugsverhältnis und Bezugsrecht?', 'Formeln: BV = \\frac{n_{alt}}{n_{neu}}; BR = \\frac{K_{alt} − K_{neu}}{BV + 1}\nBV = \\frac{2.000.000}{500.000} = 4\nBR = \\frac{30 − 20}{4 + 1} = 2 €'], ['Probe?', 'Formel: Probe: Mischkurs = alter Kurs − Bezugsrecht\nEingesetzt: 30 − 2\nErgebnis: 28 € (stimmt mit dem Mischkurs überein)']],
          res: 'Mischkurs 28 €, Bezugsrecht 2 €.' },
        nav: [],
        cards: [['Wann ist eine ordentliche Kapitalerhöhung möglich?', 'Wenn der Nennwert unter dem Börsenkurs liegt (Ausgabe nicht unter Nennwert).'], ['Formel Mischkurs?', '(n_alt P_alt + n_neu P_neu)/(n_alt + n_neu).'], ['Rechnerischer Wert des Bezugsrechts?', '(P_alt − P_neu)/(BV + 1).']] },

      { id: 'f6', t: 'Kapitalstruktur: Leverage und Modigliani-Miller', norms: ['r_EK = r_GK + (r_GK − i) · V', 'MM-Thesen'], link: 'f5',
        why: 'Wie viel Schulden sind gut? Der Leverage-Effekt zeigt die Chance, die MM-Thesen zeigen, warum in einer idealen Welt kein Optimum existiert.',
        core: ['Leverage: r_EK = r_GK + (r_GK − i) · FK/EK. Solange r_GK > i, steigt r_EK mit dem Verschuldungsgrad; ist r_GK = i, verschwindet der Effekt; ist r_GK < i, sinkt r_EK. Höhere Verschuldung erhöht die Schwankung der Eigenkapitalrendite (Kapitalstrukturrisiko).',
          'Modigliani-Miller (vollkommener Markt, keine Steuern): Unternehmenswert und Gesamtkapitalkosten sind unabhängig vom Verschuldungsgrad (These 1 und 3); die Eigenkapitalkosten steigen linear: k_EK = k_EK(0) + (k_EK(0) − k_FK) · V (These 2). Das Kapitalstrukturrisiko wird durch höhere Eigenkapitalkosten kompensiert (Risikoaversion). In der Realität wirken Steuern (Zinsen abziehbar) für und Insolvenzrisiken gegen Verschuldung.'],
        schema: ['Verschuldungsgrad V = FK/EK', 'r_EK oder k_EK mit der Leverage-Formel', 'Interpretation: Chance und Risiko', 'MM: was ist abhängig, was nicht?'],
        case: { sv: 'EK 40 Mio., FK 100 Mio. zu 6 %; Eigenkapitalkosten bei V = 0: 9 %.',
          steps: [['V?', 'Formel: V = \\frac{FK}{EK}\n\\frac{100}{40} = 2,5'], ['k_EK nach MM?', 'Formel (MM-These II): k_{EK} = k_{EK}^{u} + (k_{EK}^{u} − k_{FK}) · V\n9 % + (9 % − 6 %) · 2,5 = 16,5 %'], ['Erwartetes EK nach einer Periode?', 'Formel: EK_{1} = EK_{0} · (1 + k_{EK})\n40 · 1,165 = 46,6 Mio.']],
          res: 'k_EK 16,5 %.' },
        nav: [],
        cards: [['Leverage-Formel?', 'r_EK = r_GK + (r_GK − i) · FK/EK.'], ['MM-These 2?', 'Eigenkapitalkosten steigen linear mit dem Verschuldungsgrad: k_EK = k_EK(0) + (k_EK(0) − k_FK) · V.'], ['Was ist nach MM unabhängig vom Verschuldungsgrad?', 'Unternehmenswert und Gesamtkapitalkosten (und die Fremdkapitalkosten).'], ['Was spricht in der Realität für bzw. gegen Verschuldung?', 'Für: Steuervorteil der Zinsen; gegen: Insolvenzrisiko und -kosten.']] },

      { id: 'f7', t: 'Finanzmärkte: Auktion, Orderbuch, Effizienz', norms: ['Meistausführungsprinzip', 'Geld-Brief-Spanne', 'Markteffizienz'], link: 'f5',
        why: 'Wie entsteht ein Börsenkurs? Die Klausur lässt Eröffnungsauktionen und Orderbücher auswerten und fragt nach den Formen der Markteffizienz.',
        core: ['Auktion: Es gilt der Preis mit dem maximalen Umsatz (Meistausführung). Kaufaufträge mit Limit ≥ Preis (und „billigst“) und Verkaufsaufträge mit Limit ≤ Preis (und „bestens“) werden aggregiert; der Umsatz ist das Minimum beider Seiten. Die Seite mit Überhang wird nur teilweise bedient.',
          'Fortlaufender Handel: Geldkurs = höchstes Kauflimit, Briefkurs = niedrigstes Verkaufslimit; die Geld-Brief-Spanne misst die Liquidität (größer = illiquider). Markteffizienz: schwach (vergangene Kurse enthalten keine Prognosekraft, Chartanalyse nutzlos, Fundamentalanalyse kann helfen), mittelstark (alle öffentlichen Informationen eingepreist), stark (auch Insiderwissen eingepreist).'],
        schema: ['Aggregierte Kauf- und Verkaufsvolumina je Preis', 'Umsatz = min(Kauf, Verkauf)', 'Preis mit maximalem Umsatz', 'Teilausführung auf der Überhangseite'],
        case: { sv: 'Kaufaufträge: billigst 40, 50,2 → 60, 50,0 → 50. Verkaufsaufträge: bestens 30, 49,8 → 40, 50,0 → 60, 50,2 → 50.',
          steps: [['Aggregiert bei 50,0?', 'Formel: bei Kurs K kaufen alle mit Limit ≥ K plus billigst, verkaufen alle mit Limit ≤ K plus bestens; Umsatz = min(Kauf, Verkauf)\nEingesetzt: Kauf 40 + 60 + 50 = 150; Verkauf 30 + 40 + 60 = 130\nErgebnis: Umsatz 130'], ['Bei 50,2?', 'Kauf 100, Verkauf 180, Umsatz 100.'], ['Bei 49,8?', 'Kauf 150, Verkauf 70, Umsatz 70. Auktionspreis 50,0 mit 130 Stück; Kaufüberhang 20.']],
          res: 'Preis 50,0, Umsatz 130.' },
        nav: [],
        cards: [['Welcher Preis gilt in der Auktion?', 'Der Preis mit dem höchsten ausführbaren Umsatz (Meistausführung).'], ['Geld-Brief-Spanne?', 'Briefkurs (niedrigstes Verkaufslimit) − Geldkurs (höchstes Kauflimit); groß = geringe Liquidität.'], ['Schwache Markteffizienz?', 'Vergangene Kurse haben keinen Prognosegehalt; Fundamentalanalyse kann noch Vorteile bringen.'], ['Starke Markteffizienz?', 'Auch nicht-öffentliche (Insider-)Informationen sind eingepreist.']] },

      { id: 'f8', t: 'Rendite und Risiko', norms: ['diskrete Rendite', 'stetige Rendite ln(P_t/P_t−1)'], link: 'f7',
        why: 'Renditen werden in der Klausur diskret, annualisiert und stetig verlangt. Der Unterschied zwischen arithmetischem und geometrischem Mittel ist dabei die häufigste Falle.',
        core: ['Diskrete Rendite r_t = (P_t − P_t−1)/P_t−1 (plus Dividende). Annualisierte Rendite über T Perioden: geometrisches Mittel r̄ = ((1 + r₁)…(1 + r_T))^(1/T) − 1 = (P_T/P₀)^(1/T) − 1.',
          'Stetige Rendite R_t = ln(P_t/P_t−1); sie ist zeitadditiv, die Gesamtrendite ist die Summe der Einzelrenditen, durchschnittlich ln(P_T/P₀)/T. Deshalb eignet sie sich, wenn Renditen über die Zeit aggregiert werden. Risiko wird über die Streuung (Standardabweichung, Volatilität) gemessen: Je größer, desto unsicherer ist die realisierte Rendite.'],
        schema: ['Einzelrenditen diskret', 'Annualisiert: (P_T/P₀)^(1/T) − 1', 'Stetig: ln(P_T/P₀)/T', 'Risiko: Standardabweichung'],
        case: { sv: 'Kurse: 50, 60, 54, 63 (keine Dividende).',
          steps: [['Diskrete Renditen?', 'Formel: r_{t} = \\frac{K_{t} − K_{t−1}}{K_{t−1}}\n\\frac{60 − 50}{50} = +20 %; \\frac{54 − 60}{60} = −10 %; \\frac{63 − 54}{54} = +16,67 %'], ['Annualisiert?', 'Formel: r̄ = (\\frac{K_{T}}{K_{0}})^{1/T} − 1\n(\\frac{63}{50})^{1/3} − 1 = 1,26^{1/3} − 1\n= 8,01 %'], ['Stetig im Schnitt?', 'Formel: r̄_{stetig} = \\frac{ln(K_{T}/K_{0})}{T}\n\\frac{ln(1,26)}{3} = 7,70 %']],
          res: '8,01 % diskret annualisiert, 7,70 % stetig.' },
        nav: [],
        cards: [['Annualisierte diskrete Rendite?', '(P_T/P₀)^(1/T) − 1 (geometrisches Mittel).'], ['Durchschnittliche stetige Rendite?', 'ln(P_T/P₀)/T.'], ['Vorteil stetiger Renditen?', 'Additivität über die Zeit.'], ['Warum gelten Renditeschwankungen als Risiko?', 'Sie zeigen, wie stark realisierte Renditen vom Erwartungswert abweichen können; die Unsicherheit über das Ergebnis steigt.']] },

      { id: 'f9', t: 'Kennzahlen, Cashflow und Firmenwert', norms: ['Liquiditätsgrade', 'Anlagendeckung', 'Cashflow'], link: 'f2',
        why: 'Finanzierung endet in der Analyse: Kann das Unternehmen zahlen, ist es fristenkongruent finanziert, woher kommt und wohin geht das Geld?',
        core: ['Liquiditätsgrade: 1 = liquide Mittel / kurzfristige Verbindlichkeiten; 2 = (liquide Mittel + Forderungen) / kurzfristige Verbindlichkeiten; 3 = gesamtes Umlaufvermögen / kurzfristige Verbindlichkeiten. Anlagendeckungsgrad 1 = EK / AV (unter 1: AV nicht allein durch EK gedeckt). EK-Quote, FK-Quote und Verschuldungsgrad lassen sich ineinander umrechnen.',
          'Cashflow aus Investitionstätigkeit (vereinfacht aus Bilanzen): −(ΔSachanlagen + Abschreibungen) − ΔFinanzanlagen; positiv heißt Desinvestition, kein Wachstum. Summe der Cashflows aus betrieblicher, Investitions- und Finanzierungstätigkeit = Änderung der liquiden Mittel. Zahlungs- vs. erfolgswirksam: Abschreibungen sind erfolgs-, nicht zahlungswirksam; Gehälter beides; Zielverkauf erfolgs-, nicht zahlungswirksam. Firmenwert = Marktwert des EK − bilanzielles EK.'],
        schema: ['Kennzahl definieren (Zähler, Nenner)', 'Werte aus der Bilanz', 'Interpretation (Schwellen)', 'Cashflow-Identität nutzen'],
        case: { sv: 'Sachanlagen 200 → 170, Abschreibungen 40, Finanzanlagen unverändert. CF betrieblich 60, liquide Mittel −15.',
          steps: [['CF Investition?', 'Formel: CF Investition = −(Zunahme Sachanlagen + Abschreibungen) − Zunahme Finanzanlagen\nEingesetzt: −((170 − 200) + 40) − 0 = −(−30 + 40)\nErgebnis: −10 (Investitionen von 10)'], ['CF Finanzierung?', 'Formel: Δ liquide Mittel = CF betrieblich + CF Investition + CF Finanzierung, also CF Finanzierung = Δ liquide Mittel − CF betrieblich − CF Investition\nEingesetzt: −15 − 60 − (−10)\nErgebnis: −65 (z. B. Tilgung oder Ausschüttung)']],
          res: 'CF Inv −10, CF Fin −65.' },
        nav: [],
        cards: [['Liquiditätsgrad 2?', '(Liquide Mittel + kurzfristige Forderungen)/kurzfristige Verbindlichkeiten.'], ['Anlagendeckungsgrad 1 < 1 bedeutet?', 'Anlagevermögen nicht allein durch Eigenkapital gedeckt.'], ['CF Investition aus Bilanzen?', '−(ΔSachanlagen + Abschreibungen) − ΔFinanzanlagen.'], ['Firmenwert?', 'Marktwert des Eigenkapitals − bilanzielles Eigenkapital.']] },
    ],
  },
  BOSS: {
    inv: { t: 'Fall Bäckerei Kranz', sv: 'Bäckermeisterin Kranz kann einen Ofen A (−12.000, 4.000, 5.000, 6.000) oder B (−8.000, 0, 10.000) kaufen; Zins 5 %. Finanziert wird über ein Annuitätendarlehen von 10.000 GE, 4 Jahre, 5 %.',
      steps: [['Kapitalwerte?', 'Formel: C_{0} = −I_{0} + Σ \\frac{e_{t}}{1,05^{t}}\nEingesetzt: C_{0}^{A} = −12.000 + \\frac{4.000}{1,05} + \\frac{5.000}{1,05^{2}} + \\frac{6.000}{1,05^{3}} = −12.000 + 3.809,52 + 4.535,15 + 5.183,03; C_{0}^{B} = −8.000 + \\frac{10.000}{1,05^{2}} = −8.000 + 9.070,29\nErgebnis: C_{0}^{A} = 1.527,70; C_{0}^{B} = 1.070,29', 'i5'],
        ['Differenzreihe und Auswahl?', 'Formel: Differenzreihe A − B, Kapitalwert der Differenz; > 0 heißt A vorteilhafter\nEingesetzt: A − B = (−4.000, 4.000, −5.000, 6.000); C_{0} = −4.000 + \\frac{4.000}{1,05} − \\frac{5.000}{1,05^{2}} + \\frac{6.000}{1,05^{3}}\nErgebnis: C_{0} = 457,41 > 0 → A (= 1.527,70 − 1.070,29)', 'i6'],
        ['Laufzeitindividuelle Annuitäten?', 'a_A = 1.527,70 · ANF(5 %, 3) = 560,98; a_B = 1.070,29 · ANF(5 %, 2) = 575,61. Die Annuität spricht für B, der Kapitalwert für A: A wählen.', 'i7'],
        ['Interner Zins von B?', 'Formel: zwei Zahlungen (I_{0}, e_{T}): r = (\\frac{e_{T}}{I_{0}})^{1/T} − 1\nEingesetzt: r = (\\frac{10.000}{8.000})^{1/2} − 1\nErgebnis: r = 11,80 %', 'i8'],
        ['Annuität des Darlehens?', '10.000 · ANF(5 %, 4) = 2.820,12 GE.', 'i4']],
      res: 'A wählen; Darlehensrate 2.820,12 GE.' },
    uns: { t: 'Fall Messestand', sv: 'Ein Startup wählt zwischen drei Messeständen; Gewinne in den Zuständen schwach/mittel/stark: S (20, 20, 20), M (0, 30, 50), L (−20, 40, 90). Wahrscheinlichkeiten 0,3/0,5/0,2; Nutzen u(x) = x für µ-Prinzip.',
      steps: [['Dominanz?', 'Keine Alternative dominiert eine andere.', 'n1'], ['µ-Prinzip?', 'S 20; M 25; L 32 → L.', 'n2'], ['Maximin?', 'S (20).', 'n4'], ['Savage-Niehans?', 'Formel: Bedauern = bestes Ergebnis im Zustand − eigenes Ergebnis; wähle die Alternative mit dem kleinsten maximalen Bedauern\nEingesetzt: Spaltenmaxima 20 / 40 / 90; S (0, 20, 70), M (20, 10, 40), L (40, 0, 0); Maxima 70 / 40 / 40\nErgebnis: M oder L (beide 40)', 'n4']],
      res: 'Je nach Regel S, M oder L.' },
    fin: { t: 'Fall Nordwind AG', sv: 'Die Nordwind AG (EK 60 Mio., FK 140 Mio. zu 5 %, Gesamtkapitalrendite 8 %) plant eine Kapitalerhöhung: 4 Mio. alte Aktien zu 25 €, 1 Mio. neue zu 15 €. Außerdem gibt sie eine Kuponanleihe 3,5 %, Kurs 97 %, 5 Jahre aus.',
      steps: [['Eigenkapitalrendite vor der Erhöhung?', 'Formel: r_{EK} = r_{GK} + (r_{GK} − i) · \\frac{FK}{EK}\nEingesetzt: r_{EK} = 8 % + (8 % − 5 %) · \\frac{140}{60}\nErgebnis: r_{EK} = 15 %', 'f6'], ['Mischkurs und Bezugsrecht?', 'Formel: Mischkurs = \\frac{a · K_{alt} + n · K_{neu}}{a + n}; Bezugsrecht = \\frac{K_{alt} − K_{neu}}{\\frac{a}{n} + 1}\nEingesetzt: Mischkurs = \\frac{4 · 25 + 1 · 15}{5}; BR = \\frac{25 − 15}{4 + 1}\nErgebnis: Mischkurs 23 €; Bezugsrecht 2 €', 'f5'], ['Effektivzins der Anleihe?', 'Formel: Näherung r ≈ \\frac{Kupon + \\frac{100 − Kurs}{Laufzeit}}{Kurs}\nEingesetzt: r ≈ \\frac{0,035 + \\frac{0,03}{5}}{0,97}\nErgebnis: r ≈ 4,23 %', 'f4'], ['Wirkung der Kapitalerhöhung auf den Leverage?', 'EK steigt um 15 Mio. auf 75 Mio.; V sinkt auf 1,87, r_EK sinkt auf 13,6 %, aber auch das Risiko.', 'f6']],
      res: 'r_EK 15 %, Mischkurs 23 €, Anleihe 4,23 %.' },
  },
  LINKS: {
    i2: ['i1', 'Warum rechnet die ganze Investitionstheorie mit Zinseszins und einem einheitlichen Zins?', 'Weil der vollkommene Kapitalmarkt unterstellt wird: Jeder Betrag kann zum gleichen Zins angelegt oder geliehen werden, Zinsen werden wieder angelegt. Nur so sind Zahlungen verschiedener Zeitpunkte über Auf- und Abzinsen eindeutig vergleichbar.'],
    i3: ['i2', 'Wie hängen Annuitätenfaktor und Abzinsungsfaktoren zusammen?', 'Der Rentenbarwertfaktor ist die Summe der Abzinsungsfaktoren der Jahre 1 bis n; der ANF ist sein Kehrwert. Bei wechselnden Zinsen summiert man deshalb die einzelnen Abzinsungsfaktoren direkt.'],
    i4: ['i3', 'Warum ist die Annuität eines Darlehens dieselbe Rechnung wie ein Entnahmeplan?', 'Beides verwandelt einen Betrag in t = 0 in gleich hohe nachschüssige Zahlungen: e* = K · ANF. Beim Entnahmeplan ist der Investor Gläubiger, beim Darlehen Schuldner.'],
    i5: ['i3', 'Wann darfst du einen Kapitalwert mit dem RBF statt mit einzelnen Abzinsungen berechnen?', 'Wenn die Rückflüsse gleich hoch und nachschüssig sind (Rente): K = e₀ + Z · RBF(i, n); bei ewigen Renten K = e₀ + Z/i.'],
    i6: ['i5', 'Warum ist K(D_A,B) = K(A) − K(B)?', 'Weil der Kapitalwert linear ist: Die Barwerte der Differenzen sind die Differenzen der Barwerte.'],
    i7: ['i4', 'Was hat die Annuität einer Investition mit der Annuität eines Darlehens gemeinsam?', 'Dieselbe Formel: Betrag in t = 0 mal ANF. Beim Darlehen ist es die Rückzahlung von K, bei der Investition die gleichmäßige Verteilung des Kapitalwerts auf die Laufzeit.'],
    i8: ['i7', 'Warum kann der interne Zins bei einer Auswahl zu einer anderen Wahl führen als Kapitalwert oder Annuität?', 'Er ist eine relative Größe und blendet die Höhe des eingesetzten Kapitals und die Laufzeit aus; ein kleines Projekt mit hoher Rendite kann weniger Vermögen schaffen als ein großes mit niedrigerer.'],
    n2: ['i5', 'Was ist das µ-Prinzip, angewandt auf Kapitalwerte unsicherer Projekte?', 'Man wählt das Projekt mit dem höchsten erwarteten Kapitalwert; das entspricht Risikoneutralität und ignoriert die Streuung.'],
    n3: ['n2', 'Warum ist das Bernoulli-Prinzip allgemeiner als das µ-σ-Prinzip?', 'Es nutzt die ganze Verteilung über die Nutzenfunktion; das µ-σ-Prinzip ist nur bei bestimmten Nutzenfunktionen (quadratisch) oder Verteilungen (Normalverteilung) mit ihm vereinbar.'],
    n4: ['n3', 'Warum gibt es bei Ungewissheit kein Bernoulli-Prinzip?', 'Weil Wahrscheinlichkeiten fehlen; Erwartungswerte lassen sich nicht bilden. Die Regeln ersetzen sie durch Haltungen (Pessimismus, Optimismus, Bedauern) oder Gleichverteilung (Laplace).'],
    f2: ['f1', 'Warum ist Selbstfinanzierung für Personengesellschaften oft wichtiger als für AGs?', 'Weil sie keinen Zugang zur Börse haben und neue Gesellschafter schwer aufnehmen; Wachstum wird deshalb oft aus einbehaltenen Gewinnen finanziert.'],
    f3: ['f2', 'Wie hängen interne Mittel und Fremdfinanzierung bei einer Ersatzinvestition zusammen?', 'Erst wird der Bedarf mit den verfügbaren internen Mitteln verglichen; nur der Fehlbetrag braucht externe Finanzierung, die fristenkongruent zum Investitionsgut passen soll.'],
    f4: ['i8', 'Was ist der Effektivzins einer Anleihe aus Sicht der Investitionsrechnung?', 'Der interne Zinsfuß der Zahlungsreihe des Anleihekäufers (Ausgabekurs, Kupons, Rückzahlung). Die Näherungsformel ersetzt die exakte Berechnung.'],
    f5: ['f1', 'Warum steht die Kapitalerhöhung über die Börse vor allem der AG offen?', 'Ihre Anteile sind standardisiert und frei übertragbar; Personengesellschaften müssen neue Gesellschafter über Vertragsänderungen aufnehmen.'],
    f6: ['f3', 'Warum lohnt Fremdkapital nach dem Leverage-Effekt nur, solange r_GK > i?', 'Weil das Unternehmen auf jeden Euro Fremdkapital r_GK verdient und i zahlt; die Differenz fließt den Eigentümern zu. Ist i höher, zehrt jeder Kredit an der Eigenkapitalrendite.'],
    f7: ['f5', 'Wo wird bei einer Kapitalerhöhung gehandelt, und was hat das mit dem Mischkurs zu tun?', 'Die neuen Aktien werden auf dem Primärmarkt ausgegeben; danach bildet sich der Kurs auf dem Sekundärmarkt. Der theoretische Mischkurs ist eine Prognose für diesen Kurs, der tatsächliche kann abweichen.'],
    f8: ['i2', 'Warum ist die annualisierte Rendite ein geometrisches Mittel?', 'Wegen des Zinseszinseffekts: Renditen werden über (1 + r) multipliziert, nicht addiert. Das arithmetische Mittel würde die tatsächliche Wertentwicklung überschätzen.'],
    f9: ['f2', 'Was haben das Schema der internen Mittel und der Cashflow aus betrieblicher Tätigkeit gemeinsam?', 'Beide starten beim Jahresüberschuss, rechnen nicht zahlungswirksame Aufwendungen hinzu und korrigieren Veränderungen des Umlaufvermögens; sie zeigen, wie viel Geld der Umsatzprozess tatsächlich erzeugt.'],
  },
  DRILLS: [],
  EXAMS: [],
};
